return(function(...)
local encoded=[=[]=]
local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local map={};for i=1,64 do map[alphabet:byte(i)]=i-1 end
